  const {
  name, count, mode, show, items, label, value, custom,
  settings, context, locales, amount, date
} = props;
  return (<Card title={<Subject branch={mode}>{show ? <b>First {name}</b> : <span>Second {count}</span>}</Subject>}>Body {name}</Card>);
}

